//! Effect classes of library calls: data per frontend namespace, keyed by operation.
//!
//! A namespace without a file classifies nothing, so its calls fall to the configured
//! path table alone.

use crate::facts::{EffectKind, LibraryClass};
use crate::versioned::ByNamespace;
use serde::Deserialize;
use std::collections::BTreeMap;

const SCHEMA: &str = "rstyle.effect-classes/1";
/// Class files compiled into the engine, one per frontend namespace.
const EMBEDDED: &[&str] = &[
    include_str!("contracts/effects/go.toml"),
    include_str!("contracts/effects/cxx.toml"),
    include_str!("contracts/effects/rust.toml"),
    include_str!("contracts/effects/py.toml"),
];

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct File {
    schema: String,
    namespace: String,
    unlisted: Option<EffectKind>,
    #[serde(default)]
    io: Vec<Entry>,
    #[serde(default)]
    network: Vec<Entry>,
    #[serde(default)]
    time: Vec<Entry>,
    #[serde(default)]
    random: Vec<Entry>,
    #[serde(default)]
    panic: Vec<Entry>,
    #[serde(default)]
    global: Vec<Entry>,
    #[serde(default, rename = "unsafe")]
    unsafe_code: Vec<Entry>,
    #[serde(default)]
    unknown: Vec<Entry>,
    #[serde(default)]
    none: Vec<Entry>,
    /// No effect of its own, but it can run what it's handed: `len` runs `__len__`. Pure only where
    /// the document says the call calls nothing of the workspace's back.
    #[serde(default)]
    none_without_callback: Vec<Entry>,
    #[serde(default)]
    writes_to_memory: Vec<MemoryRule>,
}

/// A list's entry: a string covers every key it starts, and `{ exact = "..." }` only the key
/// it names, so `Option.is_some` can be listed without `Option.is_some_and`.
#[derive(Debug, Deserialize)]
#[serde(untagged)]
enum Entry {
    Prefix(String),
    Exact(Exact),
}

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct Exact {
    exact: String,
}

/// An entry's class, whether it only covers the key it names, and whether it only holds for a call
/// that calls nothing back.
#[derive(Debug)]
struct Listed {
    class: LibraryClass,
    exact: bool,
    without_callback: bool,
}

/// Operations that only write to a buffer when an argument has one of these types.
#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct MemoryRule {
    argument: usize,
    operations: Vec<String>,
    types: Vec<String>,
}

/// How to tell that one operation only writes to a buffer.
#[derive(Debug)]
pub(super) struct MemoryWrite {
    /// The position after the callee, counting from zero.
    pub argument: usize,
    pub types: Vec<String>,
}

/// The effect classes of one frontend namespace, by operation key.
#[derive(Debug, Default)]
pub struct EffectClasses {
    entries: BTreeMap<String, Listed>,
    unlisted: Option<LibraryClass>,
    memory_writes: BTreeMap<String, MemoryWrite>,
}

impl EffectClasses {
    /// The classes of a frontend namespace; none for a namespace without a file.
    pub fn of(namespace: &str) -> &'static EffectClasses {
        static CLASSES: ByNamespace<EffectClasses> = ByNamespace::empty();
        CLASSES.of(namespace, (EMBEDDED, parse))
    }

    /// The class of an operation key such as `go:os.WriteFile`, for a call that may call back into
    /// the workspace: the longest entry that starts it, where an exact entry only starts the key it
    /// names, else the file's class for an unlisted call. An entry that needs the call to call
    /// nothing back leaves it unclassified.
    pub fn class(&self, operation: &str) -> Option<LibraryClass> {
        self.classed(operation, true)
    }

    /// The class of an operation key for a call the document says calls nothing of the
    /// workspace's back, which every entry holds for.
    pub fn class_without_callback(&self, operation: &str) -> Option<LibraryClass> {
        self.classed(operation, false)
    }

    fn classed(&self, operation: &str, calls_back: bool) -> Option<LibraryClass> {
        let listed = operation
            .char_indices()
            .map(|(start, character)| start + character.len_utf8())
            .rev()
            .find_map(|end| {
                let listed = self.entries.get(&operation[..end])?;
                (!listed.exact || end == operation.len()).then_some(listed)
            });
        match listed {
            Some(listed) if listed.without_callback && calls_back => None,
            Some(listed) => Some(listed.class),
            None => self.unlisted,
        }
    }

    /// The class of a library call with no operation key.
    pub fn unlisted(&self) -> Option<LibraryClass> {
        self.unlisted
    }

    /// The rule that can keep this operation's effect in a buffer.
    pub(super) fn memory_write(&self, operation: &str) -> Option<&MemoryWrite> {
        self.memory_writes.get(operation)
    }
}

fn parse(text: &str) -> Result<(String, EffectClasses), String> {
    let file: File =
        crate::versioned::parse(text, (SCHEMA, "effect classes"), |file: &File| &file.schema)?;
    let key = |name: &str| format!("{}:{name}", file.namespace);

    let lists = [
        (&file.io, LibraryClass::Effect(EffectKind::Io)),
        (&file.network, LibraryClass::Effect(EffectKind::Network)),
        (&file.time, LibraryClass::Effect(EffectKind::Time)),
        (&file.random, LibraryClass::Effect(EffectKind::Random)),
        (&file.panic, LibraryClass::Effect(EffectKind::Panic)),
        (&file.global, LibraryClass::Effect(EffectKind::Global)),
        (&file.unsafe_code, LibraryClass::Effect(EffectKind::Unsafe)),
        (&file.unknown, LibraryClass::Effect(EffectKind::Unknown)),
        (&file.none, LibraryClass::Pure),
    ];
    let lists = lists
        .into_iter()
        .map(|(list, class)| (list, class, false))
        .chain([(&file.none_without_callback, LibraryClass::Pure, true)]);
    let mut entries = BTreeMap::new();
    for (list, class, without_callback) in lists {
        for entry in list {
            let (name, exact) = match entry {
                Entry::Prefix(name) => (name, false),
                Entry::Exact(Exact { exact }) => (exact, true),
            };
            let listed = Listed {
                class,
                exact,
                without_callback,
            };
            if entries.insert(key(name), listed).is_some() {
                return Err(format!("{name} has more than one effect class"));
            }
        }
    }

    let memory_writes = memory_writes(&file.writes_to_memory, key);
    let unlisted = file.unlisted.map(LibraryClass::Effect);
    let classes = EffectClasses {
        entries,
        unlisted,
        memory_writes,
    };
    Ok((file.namespace, classes))
}

fn memory_writes(
    rules: &[MemoryRule],
    key: impl Fn(&str) -> String,
) -> BTreeMap<String, MemoryWrite> {
    let mut writes = BTreeMap::new();
    for rule in rules {
        for operation in &rule.operations {
            let write = MemoryWrite {
                argument: rule.argument,
                types: rule.types.clone(),
            };
            writes.insert(key(operation), write);
        }
    }
    writes
}

#[cfg(test)]
mod tests {
    use super::*;

    const IO: LibraryClass = LibraryClass::Effect(EffectKind::Io);
    const UNKNOWN: LibraryClass = LibraryClass::Effect(EffectKind::Unknown);

    fn parsed(body: &str) -> Result<EffectClasses, String> {
        let text = format!("schema = \"{SCHEMA}\"\nnamespace = \"x\"\n{body}");
        parse(&text).map(|(_, classes)| classes)
    }

    #[test]
    fn go_classes_a_call_by_its_operation() {
        let go = EffectClasses::of("go");
        assert_eq!(go.class("go:os.WriteFile"), Some(IO));
        assert_eq!(go.class("go:os/exec.Cmd.Output"), Some(IO));
        assert_eq!(go.class("go:strings.ToUpper"), Some(LibraryClass::Pure));
        assert_eq!(go.class("go:len"), Some(LibraryClass::Pure));
        assert_eq!(go.class("go:unsafe.Sizeof"), Some(LibraryClass::Pure));
        assert_eq!(
            go.class("go:unsafe.Add"),
            Some(LibraryClass::Effect(EffectKind::Unsafe))
        );
        assert_eq!(go.class("go:example.com/lib.Do"), Some(UNKNOWN));
        assert_eq!(go.unlisted(), Some(UNKNOWN));
    }

    #[test]
    fn cxx_classes_a_call_by_its_library_class() {
        let cxx = EffectClasses::of("cxx");
        assert_eq!(cxx.class("cxx:fopen"), Some(IO));
        assert_eq!(cxx.class("cxx:basic_ofstream.write"), Some(IO));
        assert_eq!(cxx.class("cxx:some_library_call"), Some(UNKNOWN));
        assert_eq!(cxx.unlisted(), Some(UNKNOWN));
    }

    #[test]
    fn cxx_classes_clang_and_llvm_calls_by_their_namespaces() {
        let cxx = EffectClasses::of("cxx");
        let pure = Some(LibraryClass::Pure);
        assert_eq!(cxx.class("cxx:clang::Decl.isImplicit"), pure);
        assert_eq!(cxx.class("cxx:llvm::SmallVector.SmallVector<T,_N>"), pure);
        assert_eq!(cxx.class("cxx:llvm::sys::fs::remove"), Some(IO));
        assert_eq!(cxx.class("cxx:llvm::sys::ExecuteAndWait"), Some(IO));
        assert_eq!(cxx.class("cxx:llvm::raw_fd_ostream.write"), Some(IO));
        // A hook runs what overrides it, and a stream the caller passes does what it does.
        assert_eq!(
            cxx.class("cxx:clang::ASTConsumer.HandleTranslationUnit"),
            Some(UNKNOWN)
        );
        assert_eq!(cxx.class("cxx:llvm::raw_ostream.flush"), Some(UNKNOWN));
        // `getName` is exact, so it doesn't cover `getNameForDiagnostic`, which prints to a stream.
        assert_eq!(cxx.class("cxx:clang::NamedDecl.getName"), pure);
        assert_eq!(
            cxx.class("cxx:clang::NamedDecl.getNameForDiagnostic"),
            Some(UNKNOWN)
        );
        // Another library's function in no namespace isn't the standard `count`.
        assert_eq!(cxx.class("cxx:count"), pure);
        assert_eq!(cxx.class("cxx:::count"), Some(UNKNOWN));
    }

    #[test]
    fn rust_classes_only_what_is_pure_for_every_type() {
        let rust = EffectClasses::of("rust");
        assert_eq!(rust.class("rust:slice.iter"), Some(LibraryClass::Pure));
        assert_eq!(rust.class("rust:slice.iter_mut"), Some(LibraryClass::Pure));
        assert_eq!(
            rust.class("rust:usize.checked_add"),
            Some(LibraryClass::Pure)
        );
        assert_eq!(rust.class("rust:Vec.new"), Some(LibraryClass::Pure));
        // Allocating is no effect, and neither is panicking on a bad argument: a size too large
        // to allocate, an index past the end, or `None`.
        assert_eq!(rust.class("rust:Vec.push"), Some(LibraryClass::Pure));
        assert_eq!(rust.class("rust:owned_box.new"), Some(LibraryClass::Pure));
        assert_eq!(
            rust.class("rust:Vec.with_capacity"),
            Some(LibraryClass::Pure)
        );
        assert_eq!(
            rust.class("rust:owned_box.new_uninit_slice"),
            Some(LibraryClass::Pure)
        );
        assert_eq!(rust.class("rust:Vec.remove"), Some(LibraryClass::Pure));
        assert_eq!(rust.class("rust:Option.unwrap"), Some(LibraryClass::Pure));
        // An exact entry doesn't cover `with_capacity_in`, which takes an allocator, or
        // `unwrap_or`, which drops its default.
        assert_eq!(rust.class("rust:Vec.with_capacity_in"), None);
        assert_eq!(rust.class("rust:Option.unwrap_or"), None);
        // It runs a caller's `Ord`, or what runs depends on the implementation.
        assert_eq!(rust.class("rust:BTreeMap.get"), None);
        assert_eq!(rust.class("rust:Clone.clone"), None);
        assert_eq!(rust.class("rust:Iterator.next"), None);
        // An exact entry doesn't cover `is_some_and` or `new_cyclic`, which run a callable.
        assert_eq!(rust.class("rust:Option.is_some"), Some(LibraryClass::Pure));
        assert_eq!(rust.class("rust:Option.is_some_and"), None);
        assert_eq!(rust.class("rust:Rc.new"), Some(LibraryClass::Pure));
        assert_eq!(rust.class("rust:Rc.new_cyclic"), None);
        // A free function is keyed by the path it's defined at.
        assert_eq!(
            rust.class("rust:core::hint::must_use"),
            Some(LibraryClass::Pure)
        );
        assert_eq!(rust.class("rust:core::mem::take"), None);
        // Formatting into a `String` runs the value's own `Display` or `Debug`, and so does a
        // panic on `Err`. A `Formatter` writes to whatever the formatting started with.
        assert_eq!(
            rust.class("rust:alloc::fmt::format"),
            Some(LibraryClass::Pure)
        );
        assert_eq!(rust.class("rust:Result.unwrap"), Some(LibraryClass::Pure));
        assert_eq!(rust.class("rust:Result.unwrap_or"), None);
        assert_eq!(rust.class("rust:Formatter.write_str"), None);
        assert_eq!(rust.class("rust:ToString.to_string"), None);
        assert_eq!(rust.unlisted(), None);
    }

    #[test]
    fn rust_classes_a_trait_implementation_only_when_it_is_pure_for_every_type() {
        let rust = EffectClasses::of("rust");
        // A trait implementation is keyed by its type, or by its path when the type has no
        // compiler name. One that runs a type argument's `clone` or `From` isn't pure for
        // every type, and neither is an adapter's `next`, which runs what it wraps.
        assert_eq!(rust.class("rust:Result.branch"), Some(LibraryClass::Pure));
        assert_eq!(rust.class("rust:String.clone"), Some(LibraryClass::Pure));
        assert_eq!(rust.class("rust:SliceIter.next"), Some(LibraryClass::Pure));
        assert_eq!(
            rust.class("rust:alloc::string::{impl#39}::to_string"),
            Some(LibraryClass::Pure)
        );
        assert_eq!(rust.class("rust:Option.clone"), None);
        assert_eq!(rust.class("rust:Vec.clone"), None);
        assert_eq!(rust.class("rust:Result.from_residual"), None);
        assert_eq!(rust.class("rust:core::convert::{impl#3}::into"), None);
        assert_eq!(
            rust.class("rust:core::iter::adapters::filter::{impl#3}::next"),
            None
        );
        // An exact entry doesn't cover the inherent `usize::max_value` or `char::from_u32`.
        assert_eq!(rust.class("rust:usize.max"), Some(LibraryClass::Pure));
        assert_eq!(rust.class("rust:usize.max_value"), None);
        assert_eq!(rust.class("rust:char.from_u32"), None);
    }

    #[test]
    fn python_classes_a_call_by_its_operation() {
        let py = EffectClasses::of("py");
        let effect = |kind| Some(LibraryClass::Effect(kind));
        assert_eq!(py.class("py:open"), Some(IO));
        assert_eq!(py.class("py:subprocess.run"), Some(IO));
        assert_eq!(py.class("py:os.getenv"), effect(EffectKind::Global));
        assert_eq!(py.class("py:os.urandom"), effect(EffectKind::Random));
        assert_eq!(py.class("py:time.monotonic_ns"), effect(EffectKind::Time));
        assert_eq!(py.class("py:sys.exit"), effect(EffectKind::Panic));
        assert_eq!(py.class("py:eval"), Some(UNKNOWN));
        assert_eq!(py.class("py:list.append"), Some(LibraryClass::Pure));
        // `json.dump` writes a file, and `json.dumps` runs a value's own methods.
        assert_eq!(py.class("py:json.dump"), Some(IO));
        assert_eq!(py.class("py:json.dumps"), None);
        // `len` runs `__len__`, so it's pure only for a call that calls nothing back.
        assert_eq!(py.class("py:len"), None);
        assert_eq!(
            py.class_without_callback("py:len"),
            Some(LibraryClass::Pure)
        );
        assert_eq!(py.class("py:requests.get"), None);
        assert_eq!(py.unlisted(), None);
    }

    #[test]
    fn a_namespace_without_a_file_classifies_nothing() {
        let none = EffectClasses::of("nowhere");
        assert_eq!(none.class("nowhere:Vec.len"), None);
        assert_eq!(none.unlisted(), None);
        assert!(none.memory_write("nowhere:Vec.len").is_none());
    }

    #[test]
    fn the_longest_entry_wins_whichever_list_holds_it() {
        let classes = parsed("io = [\"pkg.\"]\nnone = [\"pkg.Pure\"]").unwrap();
        assert_eq!(classes.class("x:pkg.Write"), Some(IO));
        assert_eq!(classes.class("x:pkg.Pure"), Some(LibraryClass::Pure));
        assert_eq!(classes.class("x:pkg.Pure.Method"), Some(LibraryClass::Pure));
        assert_eq!(classes.class("x:other.Write"), None);
    }

    #[test]
    fn an_exact_entry_covers_only_the_key_it_names() {
        let classes = parsed("none = [{ exact = \"pkg.Is\" }]").unwrap();
        assert_eq!(classes.class("x:pkg.Is"), Some(LibraryClass::Pure));
        assert_eq!(classes.class("x:pkg.IsAnd"), None);
        assert_eq!(classes.class("x:pkg.I"), None);
    }

    #[test]
    fn an_exact_entry_leaves_longer_keys_to_a_shorter_entry() {
        let classes =
            parsed("io = [\"pkg.\"]\nnone = [\"pkg.Pure\", { exact = \"pkg.Is\" }]").unwrap();
        assert_eq!(classes.class("x:pkg.Is"), Some(LibraryClass::Pure));
        assert_eq!(classes.class("x:pkg.IsAnd"), Some(IO));
        assert_eq!(classes.class("x:pkg.PureToo"), Some(LibraryClass::Pure));
    }

    #[test]
    fn an_entry_without_callback_holds_only_for_a_call_that_calls_nothing_back() {
        let classes = parsed("io = [\"pkg.\"]\nnone_without_callback = [\"pkg.len\"]").unwrap();
        assert_eq!(
            classes.class_without_callback("x:pkg.len"),
            Some(LibraryClass::Pure)
        );
        // What it calls back could do anything, and the shorter entry doesn't say what.
        assert_eq!(classes.class("x:pkg.len"), None);
        // Every other entry holds either way.
        assert_eq!(classes.class_without_callback("x:pkg.Write"), Some(IO));
        let error = parsed("none = [\"pkg.A\"]\nnone_without_callback = [\"pkg.A\"]").unwrap_err();
        assert!(error.contains("pkg.A"), "{error}");
    }

    #[test]
    fn a_key_from_another_namespace_matches_nothing() {
        let classes = parsed("io = [\"pkg.\"]").unwrap();
        assert_eq!(classes.class("y:pkg.Write"), None);
    }

    #[test]
    fn a_key_can_hold_any_character() {
        let classes = parsed("io = [\"é.\"]").unwrap();
        assert_eq!(classes.class("x:é.ü"), Some(IO));
    }

    #[test]
    fn an_entry_has_one_class() {
        let error = parsed("io = [\"pkg.A\"]\nnone = [\"pkg.A\"]").unwrap_err();
        assert!(error.contains("pkg.A"), "{error}");
        let error = parsed("io = [\"pkg.A\"]\nnone = [{ exact = \"pkg.A\" }]").unwrap_err();
        assert!(error.contains("pkg.A"), "{error}");
    }

    #[test]
    fn a_memory_write_names_exact_operations() {
        let classes = parsed(
            "[[writes_to_memory]]\nargument = 1\noperations = [\"fmt.Fprint\"]\ntypes = [\"*B\"]",
        )
        .unwrap();
        let rule = classes.memory_write("x:fmt.Fprint").unwrap();
        assert_eq!(rule.argument, 1);
        assert_eq!(rule.types, ["*B"]);
        assert!(classes.memory_write("x:fmt.Fprintf").is_none());
    }

    #[test]
    fn a_file_outside_the_format_is_rejected() {
        assert!(parse("schema = \"other/1\"\nnamespace = \"x\"").is_err());
        assert!(parsed("unlisted = \"sometimes\"").is_err());
        assert!(parsed("mystery = [\"pkg.\"]").is_err());
        assert!(parsed("none = [{ prefix = \"pkg.\" }]").is_err());
        assert!(parsed("none = [{ exact = \"pkg.A\", also = \"pkg.B\" }]").is_err());
        assert!(parsed("none = [1]").is_err());
    }
}

//! Plain data passed from the rustc driver to the pure rule evaluator.

use serde::{Deserialize, Serialize};

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum EffectKind {
    Mutation,
    Io,
    Network,
    Global,
    Unsafe,
    Time,
    Random,
    Panic,
    Unknown,
}

impl EffectKind {
    pub fn name(self) -> &'static str {
        match self {
            Self::Mutation => "mutation",
            Self::Io => "io",
            Self::Network => "network",
            Self::Global => "global",
            Self::Unsafe => "unsafe",
            Self::Time => "time",
            Self::Random => "random",
            Self::Panic => "panic",
            Self::Unknown => "unknown",
        }
    }
}

/// Source budgets exclude lowered iterator bindings, while effects retain them.
#[derive(Debug, Default, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum MutationOrigin {
    #[default]
    Source,
    ForDesugaring,
}

/// A write to, or `&mut` borrow of, a place rooted at a local, param or `self`.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct MutationEvent {
    #[serde(default)]
    pub origin: MutationOrigin,
    pub root: String,
    /// Dotted field projections below `root` (empty when the root itself is mutated).
    pub field_path: String,
    pub line: usize,
    /// The write is observable outside the function: it goes through a `&mut`
    /// reference or raw pointer (`self`, `&mut` params). Mutating an owned
    /// local is state change for the mutation budget, but not a side effect.
    pub escapes: bool,
    /// Whole-object `&mut` reborrow of a workspace type (e.g. `self.helper()`):
    /// the callee performs the writes, so `escapes` is cleared and the call graph
    /// decides whether the caller inherits them.
    #[serde(default)]
    pub delegated: bool,
}

/// A call to a non-local function. Classified against the config by core, so
/// changing the config never requires re-running the compiler.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct CallEvent {
    pub callee: String,
    pub line: usize,
    /// Dispatched through `dyn`, a fn pointer or a generic callable: the target is unknown.
    #[serde(default)]
    pub dynamic: bool,
    /// What the frontend's library contract says this call does, when it says anything.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub library: Option<LibraryClass>,
    /// The identity of a callee that's a library's, as a dependence graph names it. A comparison
    /// reads this, since `library` alone can't tell a library nothing classifies from this code.
    #[serde(default, skip_serializing)]
    pub library_callee: Option<String>,
}

/// What a library contract says a call does. Config can still override it, which is why
/// it stays on the call rather than becoming an effect here.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum LibraryClass {
    Pure,
    Effect(EffectKind),
}

/// An effect the driver can decide without any config (unsafe, static mut, dyn calls).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct EffectEvent {
    pub kind: EffectKind,
    pub detail: String,
    pub line: usize,
}

/// Where a call-site argument comes from, as far as the driver can tell cheaply.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum ArgSource {
    /// The caller's own parameter (0-based, `self` excluded), possibly behind `&`, `&mut` or `*`.
    Param(usize),
    /// A literal, `const`, `static` or enum/unit constructor path.
    Const,
    /// A field projection rooted at a local, parameter or `self` (`self.opts.verbose`).
    Field,
    Other,
}

/// An `if` whose `else` only returns, around a body that could stop being nested.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct GuardClause {
    pub line: usize,
    /// Statements nested under the `if`.
    pub statements: usize,
}

/// A parameter of a function (`self` excluded).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct ParamFacts {
    /// Binding name, `_` for destructuring patterns.
    pub name: String,
    /// Declared type as written, whitespace-collapsed.
    #[serde(rename = "type")]
    pub ty: String,
    /// Number of times the body mentions the binding. A parameter whose uses are all
    /// forwards to workspace callees is a pure pass-through.
    #[serde(default)]
    pub uses: usize,
    /// What it holds when that's a plain value, however it's passed. A type someone named says
    /// more than this, so it has none.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub scalar: Option<Scalar>,
}

/// A plain value a language gives its parameters.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Scalar {
    Text,
    Integer,
    Float,
    Bool,
    Char,
}

impl Scalar {
    pub fn name(self) -> &'static str {
        match self {
            Self::Text => "text",
            Self::Integer => "integer",
            Self::Float => "float",
            Self::Bool => "bool",
            Self::Char => "char",
        }
    }
}

/// A call into workspace code (same crate or a sibling crate), by stable fn id.
/// Unlike `CallEvent` this includes same-crate callees; it is what the call graph is built from.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Edge {
    /// Stable id of the callee (see `FnFacts::id`). For trait-method calls this
    /// is the trait method, not an impl: resolve via `FnFacts::implements`.
    pub callee: String,
    pub line: usize,
    /// Dispatched through `dyn`: the concrete impl is unknown.
    #[serde(default)]
    pub dynamic: bool,
    /// A trait declares the callee without a body, so only an implementation can run.
    #[serde(default, skip_serializing_if = "std::ops::Not::not")]
    pub required: bool,
    /// One entry per callee parameter (`self` excluded), in order.
    #[serde(default)]
    pub args: Vec<ArgSource>,
}

/// Structural shape of a type as written in a signature. Raw: nothing is
/// normalized here (no `Self` substitution, no positional variables); see `shape`.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum TyShape {
    /// Struct/enum/union by stable id (see `FnFacts::id`) with its type arguments.
    Adt {
        id: String,
        args: Vec<TyShape>,
    },
    Ref {
        mutable: bool,
        inner: Box<TyShape>,
    },
    Tuple(Vec<TyShape>),
    Slice(Box<TyShape>),
    Array(Box<TyShape>),
    /// bool, char, integers, floats, `str`, `!`.
    Prim(String),
    /// Generic parameter by index.
    Param(usize),
    FnPtr,
    /// `dyn Trait`, by principal trait id when there is one.
    Dyn(String),
    Opaque,
    Other,
}

/// How a method takes `self`.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Receiver {
    /// Associated function without `self`.
    None,
    /// `self` / `mut self`.
    Value,
    /// `&self`.
    Ref,
    /// `&mut self`.
    RefMut,
    /// `self: Box<Self>`, `Rc<Self>`, `Pin<&mut Self>`, ...
    Other,
}

/// Raw signature facts of a function that lives in an `impl` block.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct SigFacts {
    /// Id of the ADT the enclosing `impl` is for (`None` for free fns and non-ADT impls).
    #[serde(default)]
    pub self_ty: Option<String>,
    /// Type arguments of the impl's self type (`Transport<TcpStream>` -> `[TcpStream]`).
    #[serde(default)]
    pub self_args: Vec<TyShape>,
    pub receiver: Receiver,
    /// Parameter types, `self` excluded.
    #[serde(default)]
    pub params: Vec<TyShape>,
    pub ret: TyShape,
    #[serde(default)]
    pub is_async: bool,
    #[serde(default)]
    pub is_unsafe: bool,
    #[serde(default)]
    pub is_const: bool,
    /// Number of the function's own generic type parameters.
    #[serde(default)]
    pub generics: usize,
}

impl TyShape {
    /// Stable, distinct text for a type (not for display: ids are full paths).
    pub fn render(&self) -> String {
        let list = |items: &[TyShape]| {
            items
                .iter()
                .map(TyShape::render)
                .collect::<Vec<_>>()
                .join(", ")
        };
        match self {
            TyShape::Adt { id, args } if args.is_empty() => id.clone(),
            TyShape::Adt { id, args } => format!("{id}<{}>", list(args)),
            TyShape::Ref { mutable, inner } => {
                format!("&{}{}", if *mutable { "mut " } else { "" }, inner.render())
            }
            TyShape::Tuple(items) => format!("({})", list(items)),
            TyShape::Slice(inner) => format!("[{}]", inner.render()),
            TyShape::Array(inner) => format!("[{}; _]", inner.render()),
            TyShape::Prim(name) => name.clone(),
            TyShape::Param(index) => format!("T{index}"),
            TyShape::Dyn(id) => format!("dyn {id}"),
            TyShape::FnPtr => "fn".into(),
            TyShape::Opaque | TyShape::Other => "_".into(),
        }
    }
}

impl SigFacts {
    /// The type that owns the method: `self_ty` plus its concrete (non-`Param`) type arguments,
    /// so `impl Transport<TcpStream>` and `impl Transport<UnixStream>` are different owners.
    pub fn owner(&self) -> Option<String> {
        let id = self.self_ty.as_deref()?;
        let concrete: Vec<String> = self
            .self_args
            .iter()
            .filter(|a| !matches!(a, TyShape::Param(_)))
            .map(TyShape::render)
            .collect();
        Some(if concrete.is_empty() {
            id.to_string()
        } else {
            format!("{id}<{}>", concrete.join(", "))
        })
    }
}

/// Kind of a program-dependence-graph node. Front-end neutral: a MIR emitter could
/// produce the same kinds.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum NodeKind {
    Param,
    /// Destructuring `let` / `if let` (simple `let x = e` is transparent: `x` is `e`'s node).
    Let,
    Call,
    Macro,
    Field,
    Lit,
    Branch,
    Match,
    /// `for` loops and `Iterator::for_each` closures: the same abstract iteration.
    Iterate,
    /// `while` and `loop`.
    Loop,
    Return,
    Try,
    /// Opaque: the body is not descended into.
    Closure,
    Cast,
    /// Operators, struct/tuple/array construction, indexing, assignment (see `detail`).
    Op,
    /// Canonical value construction (`normalize`): `Err(E::Bad("x"))`, `None`, `Ok(())` as one node.
    /// Never emitted by the driver.
    Ctor,
    /// Canonical decision (`normalize`): `if`, `else if`, `if let` and `match` as one node.
    Case,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum EdgeKind {
    Data,
    Ctrl,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct PdgNode {
    pub kind: NodeKind,
    /// Raw type of the value this node produces, when known.
    #[serde(default)]
    pub ty: Option<TyShape>,
    /// Stable id of the called function (`Call`, and `Lit` for fn items). Kept for hole detection.
    #[serde(default)]
    pub callee_id: Option<String>,
    /// Raw signature of the callee; core normalizes it into the node label (signature class).
    #[serde(default)]
    pub callee_sig: Option<SigFacts>,
    #[serde(default)]
    pub macro_name: Option<String>,
    #[serde(default)]
    pub lit_kind: Option<String>,
    /// Operator, field name or literal text; never part of the label.
    #[serde(default)]
    pub detail: String,
    #[serde(default)]
    pub line: usize,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub struct PdgEdge {
    pub from: usize,
    pub to: usize,
    pub kind: EdgeKind,
    /// Operand position for data edges (receiver is 0), arm index for control edges.
    #[serde(default)]
    pub arg_pos: usize,
}

/// Dependence graph of one function body. No execution-order edges, so
/// reordering independent statements does not change it.
#[derive(Debug, Clone, Default, PartialEq, Eq, Serialize, Deserialize)]
pub struct Pdg {
    pub nodes: Vec<PdgNode>,
    pub edges: Vec<PdgEdge>,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct FnFacts {
    /// Stable id: `<crate>::<def path>` with impl disambiguators (`{impl#0}`).
    /// Identical across lib/test targets, unlike the display `name`.
    #[serde(default)]
    pub id: String,
    /// For a trait-impl method, the id of the trait method it implements.
    #[serde(default)]
    pub implements: Option<String>,
    /// Workspace-relative path with `/` separators.
    pub path: String,
    pub line: usize,
    pub column: usize,
    pub name: String,
    /// Parameter count excluding `self`.
    pub params: usize,
    /// Name, type and use count of each parameter (`self` excluded).
    #[serde(default)]
    pub param_list: Vec<ParamFacts>,
    pub has_self: bool,
    pub statements: usize,
    /// Statements (plus the tail expression) directly in the body block; 1 for a
    /// non-block body. 0 in facts from older runs, which `fn_spacing` skips.
    #[serde(default)]
    pub top_statements: usize,
    /// Source-level complexity. Older facts omit it; absent data is unavailable.
    #[serde(default)]
    pub complexity: Option<crate::complexity::Measurement>,
    /// Source text from the `fn` signature through the closing brace.
    pub source: String,
    /// The comment line directly above the function (attributes skipped), if any.
    pub preceding_line: String,
    pub mutations: Vec<MutationEvent>,
    pub calls: Vec<CallEvent>,
    pub effects: Vec<EffectEvent>,
    /// Calls into workspace functions, in source order.
    #[serde(default)]
    pub edges: Vec<Edge>,
    /// Ids of workspace types this function writes through (sorted, deduplicated).
    #[serde(default)]
    pub mutated_types: Vec<String>,
    /// Signature shape; `None` for free functions and facts from older runs.
    #[serde(default)]
    pub sig: Option<SigFacts>,
    /// Each `if` that could be a guard clause.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub guard_clauses: Vec<GuardClause>,
    /// Dependence graph; only present when the driver ran in semantic (`patterns`) mode.
    #[serde(default)]
    pub pdg: Option<Pdg>,
    /// The terms its language's labels use. A label says them, so they aren't a fact to keep.
    #[serde(skip)]
    pub wording: crate::wording::Wording,
}

impl FnFacts {
    /// The function's source as whole lines: `source` starts at the function's column, so its
    /// first line is indented back to it.
    pub fn whole_lines(&self) -> String {
        format!(
            "{}{}",
            " ".repeat(self.column.saturating_sub(1)),
            self.source
        )
    }

    fn key(&self) -> (&str, usize, usize, &str) {
        (&self.path, self.line, self.column, &self.name)
    }
}

/// Merges facts from several compilation targets: sorted, and deduplicated by
/// location and name (the first occurrence in input order wins).
pub fn merge(mut facts: Vec<FnFacts>) -> Vec<FnFacts> {
    facts.sort_by(|a, b| a.key().cmp(&b.key()));
    facts.dedup_by(|a, b| a.key() == b.key());
    facts
}

#[cfg(test)]
pub fn sample(name: &str) -> FnFacts {
    FnFacts {
        id: format!("krate::{name}"),
        implements: None,
        path: "src/lib.rs".into(),
        line: 1,
        column: 1,
        name: name.into(),
        params: 0,
        param_list: vec![],
        has_self: false,
        statements: 1,
        top_statements: 2,
        complexity: None,
        source: format!("fn {name}() {{}}"),
        preceding_line: String::new(),
        mutations: vec![],
        calls: vec![],
        effects: vec![],
        edges: vec![],
        mutated_types: vec![],
        sig: None,
        guard_clauses: vec![],
