pub fn evaluate_and_retain(
    facts: Vec<FnFacts>,
    cfg: &Config,
) -> Result<(Report, Vec<FnFacts>), String> {
    evaluate_inputs(facts, cfg, Retention::Report, None)
        .map(|evaluation| (evaluation.report, evaluation.facts))
}

